<section class="pk-s pk-gl"><div class="pk-w"><div class="pk-gl-h"><p class="pk-ey">From the cold</p><h2 class="rv">Made for minus</h2></div><div class="pk-shards"><figure class="pk-sh rv" style="clip-path:polygon(0 6%,100% 0,92% 100%,6% 92%)"><img src="https://images.unsplash.com/photo-1612698693085-53829396ef41?auto=format&fit=crop&w=420&h=560&q=75" alt="a woman with snow on her face in a winter hood" width="420" height="560" loading="lazy"></figure><figure class="pk-sh rv" style="clip-path:polygon(8% 0,100% 8%,100% 94%,0 100%)"><img src="https://images.unsplash.com/photo-1705205149194-b685049b74ce?auto=format&fit=crop&w=420&h=560&q=75" alt="a person in a yellow parka" width="420" height="560" loading="lazy"></figure><figure class="pk-sh rv" style="clip-path:polygon(0 0,94% 6%,100% 100%,4% 94%)"><img src="https://images.unsplash.com/photo-1612736870754-166527523f02?auto=format&fit=crop&w=420&h=560&q=75" alt="a person in an orange parka seen from behind in the snow" width="420" height="560" loading="lazy"></figure><figure class="pk-sh rv" style="clip-path:polygon(6% 4%,100% 0,96% 96%,0 100%)"><img src="https://images.unsplash.com/photo-1611163475112-0946a7823bd1?auto=format&fit=crop&w=420&h=560&q=75" alt="a girl in a parka with a fur trimmed hood" width="420" height="560" loading="lazy"></figure><figure class="pk-sh rv" style="clip-path:polygon(0 8%,96% 0,100% 92%,8% 100%)"><img src="https://images.unsplash.com/photo-1721746930135-f9401608be2f?auto=format&fit=crop&w=420&h=560&q=75" alt="a woman in a purple puffer jacket" width="420" height="560" loading="lazy"></figure></div></div></section>

